import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "./DetailsProduct.scss";

const DetailsProduct = () => {
  const { productId } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch("/products.json");

        if (!response.ok) {
          throw new Error("Erro ao carregar os produtos");
        }

        const data = await response.json();
        const selectedProduct = data.find((p) => String(p.productId) === String(productId));
        console.log("Produto selecionado:", selectedProduct);
        setProduct(selectedProduct);
      } catch (error) {
        console.error("Erro ao carregar o produto:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [productId]);

  if (loading) return <p>Carregando...</p>;
  if (!product) return <p>Produto não encontrado.</p>;

  // Extraindo imagens corretamente
  const images =
    product.items?.[0]?.images?.map((image) => image.imageUrl) || ["/no-image.jpg"];

  // Extraindo preços corretamente
  const firstItem = product.items?.[0];
  const seller = firstItem?.sellers?.[0];

  const priceVista = seller?.priceVista ?? firstItem?.priceVista ?? null;
  const priceParcelado = seller?.priceParcelado ?? firstItem?.priceParcelado ?? null;
  const installments = seller?.installments ?? firstItem?.installments ?? null;

  return (
    <div className="details-product">
      <div className="product-gallery">
        {images.map((image, index) => (
          <img key={index} src={image} alt={`Produto ${index + 1}`} />
        ))}
      </div>

      <div className="product-info">
        <h1>{product.productName}</h1>
        <p className="description">{product.metaTagDescription || "Sem descrição disponível."}</p>
        <p className="price">
          {installments && priceParcelado
            ? `${installments}x de R$ ${priceParcelado.toFixed(2)}`
            : priceVista
            ? `À vista por R$ ${priceVista.toFixed(2)}`
            : "Preço indisponível"}
        </p>
        <button className="add-to-cart">ADICIONAR À SACOLA</button>
      </div>
    </div>
  );
};

export default DetailsProduct;
